function migrateSave(raw){const base=defaultSave(),x=raw&&typeof raw==='object'?raw:{};const migrated=Object.assign(base,x,{activeSkills:Array.isArray(x.activeSkills)&&x.activeSkills.length?x.activeSkills:base.activeSkills,selectedSkill:x.selectedSkill||base.selectedSkill,settings:Object.assign(base.settings,x.settings||{}),stats:Object.assign(base.stats,x.stats||{}),inheritance:Object.assign(base.inheritance,x.inheritance||{}),achievements:Object.assign(base.achievements,x.achievements||{}),achievementPoints:Number.isFinite(x.achievementPoints)?x.achievementPoints:0});for(const [id,defaults] of Object.entries(defaultSave().achievements))migrated.achievements[id]=Object.assign({},defaults,migrated.achievements[id]||{},{target:defaults.target});migrated.version=3;return migrated}
