function persist(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(save))}catch(e){if(saveWritable){saveWritable=false;showNotice('storageWarning','当前浏览器不允许写入本地存储，本局进度不会被保存','#3a2a17f2','#e2bc78','#f3e4c6')}}updateTop()}
