function checkAntiSynergies(){const active=[];for(const anti of antiSynergies){const ok=anti.conds.every(c=>c.type==='terrain'?(game&&game.terrain&&game.terrain.id===c.id):has(c.id));if(ok)active.push(anti)}return active}
const rarityWeight={common:100,rare:45,epic:18,legendary:6};
function weightedPick(pool,r,weights=rarityWeight,bonus=null){if(!pool.length)return null;const w=item=>(weights[item.rarity]||100)*(bonus?bonus(item):1);let total=0;for(const item of pool)total+=w(item);let roll=r()*total;for(let i=0;i<pool.length;i++){roll-=w(pool[i]);if(roll<=0)return pool.splice(i,1)[0]}return pool.pop()}
const pityConf={start:6,step:.35,max:3};
function effectiveRarityWeight(){const weights=Object.assign({},rarityWeight);if(game.evolutions.collector==='treasure'){weights.epic=30;weights.legendary=14}if(has('voidmouth')){weights.rare*=1.5;weights.epic*=1.5;weights.legendary*=1.5}const dry=(game&&game.dryDraws)||0;if(dry>=pityConf.start){const mult=Math.min(pityConf.max,1+(dry-pityConf.start+1)*pityConf.step);weights.epic*=mult;weights.legendary*=mult}return weights}
function relicPool(){return relics.filter(r=>r.id!=='mark'&&(baseUnlocked.includes(r.id)||save.unlockedRelicIds.includes(r.id)))}
function stacks(id){return game.relics[id]||0}
function has(id){return stacks(id)>0}
