function maxShield(){return 3}
function grantShield(seconds,source='效果'){if(!game)return 0;const before=game.shield||0;game.shield=clamp(Math.max(before,seconds),0,maxShield());game.lastShieldSource=source;return game.shield-before}
function recordEvent(type,detail,value){if(!game)return;if(!game.log)game.log=[];game.log.push({t:+(game.elapsed||0).toFixed(2),type,detail,value});if(game.log.length>80)game.log.splice(0,game.log.length-80)}
function addScore(value,reason=''){if(!game)return 0;const gained=Math.round(value||0);if(!gained)return 0;game.score=Math.max(0,(game.score||0)+gained);recordEvent('score',reason,gained);return gained}
function removeSnakeSegments(n,reason=''){if(!game)return 0;const removed=Math.min(Math.max(0,n|0),Math.max(0,game.snake.length-3));for(let i=0;i<removed;i++)game.snake.pop();if(removed)recordEvent('shrink',reason,-removed);return removed}
function synergyLevel(syn){const ids=Object.keys(game.relics).filter(id=>game.relics[id]>0&&relicById[id]);const relevant=ids.filter(id=>relicById[id].tags.some(t=>syn.tags.includes(t)));const total=relevant.reduce((n,id)=>n+game.relics[id],0);if(relevant.some(id=>game.evolutions[id]))return 3;return total>=3?2:1}
function wouldTriggerAnti(r){const active=checkAntiSynergies();return antiSynergies.filter(a=>!active.includes(a)&&a.conds.every(c=>c.type==='terrain'?(game.terrain&&game.terrain.id===c.id):(c.id===r.id||has(c.id))))}
function relicContextBonus(r){let factor=1;if(stacks(r.id)>0)factor*=1.2;const active=new Set(activeSynergies().map(s=>s.name));const tags=new Set([...Object.keys(game.relics).filter(id=>has(id)).flatMap(id=>relicById[id]?relicById[id].tags:[]),...r.tags]);if(synergyDefs.some(s=>!active.has(s.name)&&s.tags.every(t=>tags.has(t))))factor*=1.25;if(wouldTriggerAnti(r).length)factor*=.75;return factor}
function updatePity(cards){if(!game||!cards||!cards.length)return;const hit=cards.some(c=>c.rarity==='epic'||c.rarity==='legendary');game.dryDraws=hit?0:(game.dryDraws||0)+1;recordEvent('draw',hit?'高稀有':'普通',game.dryDraws)}

