function hasSyn(name){return activeSynergies().some(s=>s.name===name)}
function hasAnti(a,b){return checkAntiSynergies().some(x=>x.conds.length===2&&x.conds.every(c=>c.type==='relic'&&(c.id===a||c.id===b)))}
function maxArmor(){return 2+stacks('armor')}
function curseStacks(){return Object.keys(game.relics).reduce((n,id)=>n+((relicById[id]&&relicById[id].tags.includes('curse'))?game.relics[id]:0),0)}
