function spawnEnemy(type='normal',position=null){
 if(game.enemies.length>=COMBAT.maxEnemies)return null;
 if(type===true)type='tracker';
 if(type==='summoner'&&game.enemies.filter(e=>e.type==='summoner').length>=2)return null;
 const p=position||freeCell();if(!p)return null;
 const enemy={x:p.x,y:p.y,px:p.x,py:p.y,dx:1,dy:0,type,life:0,hit:0,slow:0,moveClock:0,trail:type==='splitter_small'?1:type==='tracker'?3:2,hp:type==='guardian'?2:1,maxHp:type==='guardian'?2:1,tracker:type==='tracker'};
 if(type==='guardian')enemy.spawnZone={x:p.x,y:p.y};
 if(type==='bomber')enemy.chargeTimer=0;
 if(type==='summoner')enemy.summonTimer=COMBAT.summonInterval;
 game.enemies.push(enemy);return enemy;
}
const baseSpawnEnemy=spawnEnemy;
spawnEnemy=function(type='normal',position=null){const e=baseSpawnEnemy(type,position);if(e&&['charger','sentinel','burrower','leech','mirror'].includes(type)){e.special=true;e.hp=type==='sentinel'?2:1;e.maxHp=e.hp;e.fireTimer=type==='sentinel'?4:0;e.burrowTimer=type==='burrower'?2:0;e.history=[];e.trail=type==='mirror'?4:e.trail}return e};
