 const color={guardian:'#4a7c9e',bomber:'#ff8a4c',splitter:'#9d6bff',splitter_small:'#66f2a2',summoner:'#d4af37'}[enemy.type]||'#ff647c';
 game.floaters.push({x:enemy.x,y:enemy.y,text:'击杀 +'+reward,color,life:1});burst(enemy.x,enemy.y,color,'explosion');
 if(enemy.type==='bomber')SFX.explosion();else if(enemy.type==='summoner')beep(960,.12,'triangle');else if(enemy.type==='splitter')beep(480,.12,'sawtooth');else if(enemy.type==='guardian')beep(140,.14,'square');else SFX.killEnemy();shake(3,.15);
