function updateSpecialEnemies(dt){
 if(!game)return;
 const h=game.snake[0];
 for(const e of [...game.enemies]){
  if(!game.enemies.includes(e))continue;
  if(e.type==='charger'){
   if(e.chargeTimer===undefined){e.chargeTimer=.8;e.target={x:h.x,y:h.y};e.dx=Math.sign(h.x-e.x)||1;e.dy=Math.sign(h.y-e.y)||0}
   if(e.chargeTimer>0){e.chargeTimer-=dt;e.specialFrozen=true;if(e.chargeTimer<=0){e.specialFrozen=false;e.dashLeft=4}}
   if(e.specialFrozen)e.moveClock=-999;
   else if(e.dashLeft>0){e.moveClock=-999;const nx=e.x+e.dx,ny=e.y+e.dy;if(nx<0||nx>=GRID||ny<0||ny>=GRID||terrainBlocked(nx,ny)||game.obstacles.some(o=>o.x===nx&&o.y===ny)){e.dashLeft=0;e.cooldown=2}else{e.x=nx;e.y=ny;e.dashLeft--;if(e.x===h.x&&e.y===h.y)collideEnemy(e)}}
   else {e.cooldown=Math.max(0,(e.cooldown||0)-dt);if(e.cooldown<=0)e.chargeTimer=.8}
  } else if(e.type==='sentinel'){
   e.moveClock=-999;e.fireTimer=(e.fireTimer??4)-dt;
   if(e.fireTimer<=.9&&e.fireTimer>0)e.laserWarning=true;
   if(e.fireTimer<=0){e.fireTimer=4;e.laserWarning=false;e.laser={x:Math.sign(h.x-e.x),y:Math.sign(h.y-e.y)};let x=e.x,y=e.y;for(let n=0;n<GRID;n++){x+=e.laser.x;y+=e.laser.y;if(x<0||x>=GRID||y<0||y>=GRID||terrainBlocked(x,y)||game.obstacles.some(o=>o.x===x&&o.y===y))break;if(x===h.x&&y===h.y){if(has('insulator')&&game.r()<.5){}else if(game.shield>0)game.shield--;else die('炮台射线')}}}
  } else if(e.type==='burrower'){
   e.burrowTimer=(e.burrowTimer??2)-dt;e.hidden=e.burrowTimer>0;if(e.hidden){e.moveClock=-999;const cells=[];for(let dx=-3;dx<=3;dx++)for(let dy=-3;dy<=3;dy++){const x=h.x+dx,y=h.y+dy;if(Math.abs(dx)+Math.abs(dy)<=3&&terrainFree(x,y)&&!game.food.some(f=>f.x===x&&f.y===y))cells.push({x,y})}const p=cells.length?pick(cells,game.r):{x:clamp(h.x+3,1,GRID-2),y:clamp(h.y,1,GRID-2)};e.x=p.x;e.y=p.y}else if(!e.emerged){e.emerged=true;e.life=0;e.floaters=0;game.floaters.push({x:e.x,y:e.y,text:'掘地者出现',color:'#c59670',life:1})}
  } else if(e.type==='leech'){
   if(Math.abs(h.x-e.x)+Math.abs(h.y-e.y)<=3){e.attached=true;game.leechSlow=true}else e.attached=false;
  } else if(e.type==='mirror'){
   e.history=e.history||[];e.history.push({x:h.x,y:h.y});if(e.history.length>18)e.history.shift();const p=e.history[0];if(p){e.x=p.x;e.y=p.y}if(e.x===h.x&&e.y===h.y&&game.invuln<=0){game.invuln=.6;game.shield>0?game.shield--:die('镜像轨迹')}
  }
 }
}
