function moveEnemies(dt=.16){
 const opts=[{x:1,y:0},{x:-1,y:0},{x:0,y:1},{x:0,y:-1}];
 for(const e of [...game.enemies]){
   if(!game.enemies.includes(e))continue;
   if(e.special)continue;
   e.hit=Math.max(0,(e.hit||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);
   const h=game.snake[0],dist=Math.abs(h.x-e.x)+Math.abs(h.y-e.y);
   if(e.type==='bomber'){
     if(!e.chargeTimer&&dist<=2)e.chargeTimer=COMBAT.bombDelay;
     if(e.chargeTimer>0){e.chargeTimer-=dt;if(e.chargeTimer<=0){explodeEnemy(e);if(state!==STATES.PLAYING)return}continue}
   }
   if(e.type==='summoner'){e.summonTimer-=dt;if(e.summonTimer<=0){e.summonTimer+=COMBAT.summonInterval;spawnEnemy('tracker')}}
   e.moveClock=(e.moveClock||0)+dt;
   const interval=(e.type==='guardian'?.45:e.type==='summoner'?.5:e.type==='splitter_small'?.12:.26)*(e.slow>0?2:1);
   if(e.moveClock<interval)continue;e.moveClock%=interval;
   e.px=e.x;e.py=e.y;
   let d=pick(opts,game.r);
   if(e.type==='guardian'){
     const z=e.spawnZone;const valid=opts.filter(o=>Math.abs(e.x+o.x-z.x)<=1&&Math.abs(e.y+o.y-z.y)<=1);d=pick(valid,game.r)||{x:0,y:0};
   }else if(e.type==='summoner'&&dist<5){d=Math.abs(h.x-e.x)>Math.abs(h.y-e.y)?{x:-Math.sign(h.x-e.x),y:0}:{x:0,y:-Math.sign(h.y-e.y)}}
   else if(game.bait||e.tracker||e.type==='bomber'){const t=game.bait||h;d=Math.abs(t.x-e.x)>Math.abs(t.y-e.y)?{x:Math.sign(t.x-e.x),y:0}:{x:0,y:Math.sign(t.y-e.y)}}
   const nx=clamp(e.x+d.x,0,GRID-1),ny=clamp(e.y+d.y,0,GRID-1);
   if(!game.obstacles.some(o=>!o.thorn&&o.x===nx&&o.y===ny)&&!game.enemies.some(other=>other!==e&&other.x===nx&&other.y===ny)){e.x=nx;e.y=ny;e.dx=d.x;e.dy=d.y}
   const thorn=game.obstacles.find(o=>o.thorn&&o.x===e.x&&o.y===e.y);const ghost=game.obstacles.find(o=>o.afterimage&&o.x===e.x&&o.y===e.y);
   if(ghost)damageEnemy(e,1,'残影');
   if(thorn){if(thorn.venom)e.slow=2;damageEnemy(e,1,'荆棘尾迹')}
   if(!game.enemies.includes(e))continue;
   if(e.x===h.x&&e.y===h.y){collideEnemy(e);if(state!==STATES.PLAYING)return}
 }
 for(const a of game.allies){
   a.life-=dt;a.attackTimer=(a.attackTimer||0)-dt;
   const e=game.enemies.find(e=>Math.abs(e.x-a.x)+Math.abs(e.y-a.y)<=(a.enhanced?3:2));
   if(e&&a.attackTimer<=0){damageEnemy(e,a.enhanced?2:1,'友方蛇');a.attackTimer=.6}
   if(a.life<=0){if(game.evolutions.egg==='hatch')game.enemies.filter(e=>Math.max(Math.abs(e.x-a.x),Math.abs(e.y-a.y))<=2).forEach(e=>damageEnemy(e,1,'爆裂孵化'));if(hasSyn('召唤流'))growSnake(3)}
 }
 game.allies=game.allies.filter(a=>a.life>0);
}
function explodeEnemy(enemy){
 const inRange=p=>Math.max(Math.abs(p.x-enemy.x),Math.abs(p.y-enemy.y))<=1;
 game.enemies.splice(game.enemies.indexOf(enemy),1);
 game.food=game.food.filter(f=>!inRange(f));game.obstacles=game.obstacles.filter(o=>!inRange(o));
 game.enemies.filter(inRange).forEach(e=>damageEnemy(e,2,'爆炸'));
 burst(enemy.x,enemy.y,'#ff8a4c','explosion');SFX.explosion();shake(8,.3);flash('#ff8a4c',.18);
 if(inRange(game.snake[0])&&game.invuln<=0){if(game.skillPhase){game.skillPhase=false;game.invuln=1}else if(game.shield>0){game.shield=0;game.invuln=1}else if(game.armorCharges>0){game.armorCharges--;game.invuln=1}else die('自爆兵爆炸')}
 if(!game.food.length)spawnFood();
}
function showUpgrade(){state=STATES.UPGRADE_CHOICE;const over=document.createElement('div');over.className='overlay';over.id='upgradeOverlay';over.innerHTML='<div class="overlay-card"><div class="between"><div><h2>选择遗物</h2><p class="hint">按 1 / 2 / 3 选择 · R/F 刷新 · 空格/0/S 跳过</p></div><span class="pill">升级 '+game.level+'</span></div><div class="cards"></div><div class="between"><button id="refreshInfo">R/F 刷新</button><button id="skipRelic">空格/0/S 跳过</button></div></div>';$('#gameWrap').appendChild(over);function renderCards(){const pool=relicPool().filter(r=>stacks(r.id)<r.max);const cards=[];const weights=effectiveRarityWeight();while(cards.length<3&&pool.length)cards.push(weightedPick(pool,game.r,weights,relicContextBonus));game.lastCards=cards;if(game.forceRare&&cards.length&&!cards.some(c=>c.rarity&&c.rarity!=='common')){const bi=pool.findIndex(r=>r.rarity&&r.rarity!=='common');if(bi>=0)cards[cards.length-1]=pool.splice(bi,1)[0]}const box=over.querySelector('.cards');box.innerHTML='';cards.forEach((r,i)=>{const c=document.createElement('div');const isInherit=save.inheritance.relicId===r.id;c.className='relic-card'+(isInherit?' inherit-card':'');c.tabIndex=0;const evoText=isInherit&&game.evolutions[r.id]?`<span class="evolution-badge">${evolutions[r.id].find(e=>e[0]===game.evolutions[r.id])[1]}</span>`:'';c.innerHTML=`<span class="${'rarity-'+r.rarity}">${isInherit?'🔒 传承 · ':''}${r.rarity.toUpperCase()}</span><h3>${i+1}. ${r.name}</h3><div>${r.tags.map(t=>`<span class="tag">${tagNames[t]||t}</span>`).join(' ')}</div><p>${r.desc}</p><span class="stack">${stacks(r.id)}/${r.max} → ${Math.min(stacks(r.id)+1,r.max)}/${r.max}</span>${evoText}`;const info=relicChoiceInfo(r);if(info){const detail=document.createElement('span');detail.className='synergy-preview';detail.textContent=info;c.appendChild(detail)}c.onclick=()=>chooseRelic(r.id);const current=new Set(activeSynergies().map(s=>s.name)),tags=new Set([...Object.keys(game.relics).filter(id=>has(id)).flatMap(id=>relicById[id].tags),...r.tags]);const unlocks=synergyDefs.filter(s=>!current.has(s.name)&&s.tags.every(t=>tags.has(t)));if(unlocks.length){const note=document.createElement('span');note.className='synergy-preview';note.textContent='可激活：'+unlocks.map(s=>s.name).join(' · ');c.appendChild(note)}box.appendChild(c)});$('#refreshInfo').textContent=`R/F 刷新（${game.refreshes}）`;$('#refreshInfo').disabled=game.refreshes<1}function chooseRelic(id){updatePity(game.lastCards);game.forceRare=false;addRelic(id);state=STATES.PLAYING;if(stacks(id)>=relicById[id].max&&!game.evolutions[id]&&evolutions[id]){over.remove();showEvolution(id);return}over.remove();updateHud()}renderCards();$('#refreshInfo').onclick=()=>{if(game.refreshes<1)return;game.refreshes--;renderCards();SFX.refresh()};$('#skipRelic').onclick=()=>{if(has('collector')){game.hoarderStacks=(game.hoarderStacks||0)+1;game.floaters.push({x:GRID/2,y:GRID/2,text:'囤积 +1（共 '+game.hoarderStacks+' 栈，按 E 兑换）',color:'#ffd166',life:1.6});SFX.relicGet()}addScore(game.evolutions.collector==='discount'?15:has('collector')?3:0,'跳过升级');if(game.evolutions.collector==='discount')grantShield(1,'折价交易');updatePity(game.lastCards);over.remove();state=STATES.PLAYING;updateHud()};over.addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='1'||e.key==='2'||e.key==='3'){const card=over.querySelectorAll('.relic-card')[Number(e.key)-1];if(card){e.preventDefault();card.click()}}else if(e.key==='r'||e.key==='R'||e.key==='f'||e.key==='F'){e.preventDefault();$('#refreshInfo').click()}else if(e.key===' '||e.key==='0'||e.key==='s'||e.key==='S'){e.preventDefault();$('#skipRelic').click()}});over.tabIndex=-1;over.focus();over.querySelector('.cards').addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.classList.contains('relic-card'))e.target.click()});}
function showChoiceOverlay(title,items,onPick,lockText='确认锁定'){const over=document.createElement('div');over.className='overlay';over.id='choiceOverlay';over.innerHTML=`<div class="overlay-card"><div class="between"><div><h2>${title}</h2><p class="hint">选定后立即锁定，本界面没有撤销。</p></div><span class="pill">${lockText}</span></div><div class="cards"></div></div>`;$('#gameWrap').appendChild(over);const box=over.querySelector('.cards');items.forEach((r,i)=>{const c=document.createElement('div');c.className='relic-card';c.innerHTML=`<span class="rarity-${r.rarity}">${r.rarity}</span><h3>${r.name}</h3><p>${r.desc}</p><span class="stack">层数 ${stacks(r.id)}</span>`;c.onclick=()=>{onPick(r.id);over.remove()};box.appendChild(c)})}
function useMark(){if(!game.mark||!Object.keys(game.relics).length)return;state=STATES.INHERIT_MARK;showChoiceOverlay('传承印记：改写传承',Object.keys(game.relics).filter(id=>id!=='mark').map(id=>relicById[id]),id=>{save.inheritance={enabled:true,relicId:id,keepStack:save.unlockedMetaUpgrades.inherit_stack?stacks(id):1,evolution:game.evolutions[id]||null,lockedAt:Date.now()};game.mark=false;delete game.relics.mark;checkAchievement('inherit_3x',save.achievements.inherit_3x.progress+1);persist();state=STATES.PLAYING;beep(960,.14,'triangle')},'覆盖当前传承')}
function pause(){if(state===STATES.PLAYING){state=STATES.PAUSED;showPause();updateHud()}else if(state===STATES.PAUSED){$('#pauseOverlay')?.remove();state=STATES.PLAYING;updateHud()}}
function showPause(){const o=document.createElement('div');o.className='overlay';o.id='pauseOverlay';o.innerHTML='<div class="overlay-card"><div class="between"><h2>暂停</h2><button id="resume">继续</button></div><p class="hint" style="margin:8px 0">传承状态、当前 Build、进化与祭坛效果</p><div class="relic-list" id="pauseRelics"></div><div id="pauseEffects" class="relic-list" style="margin-top:8px"></div><p class="hint" style="margin-top:12px">P / Esc 继续 · Q 使用传承印记 · X 主动献祭 · 空格技能</p></div>';$('#gameWrap').appendChild(o);if(game.pendingEvolution){const warning=document.createElement('div');warning.className='pause-warning';warning.innerHTML=`<span class="pill gold">⚠ 有待选择的进化</span><button id="resumeEvolution">立即选择</button>`;o.querySelector('.overlay-card').prepend(warning);o.querySelector('#resumeEvolution').onclick=()=>{pause();showEvolution(game.pendingEvolution)}}const l=o.querySelector('#pauseRelics');Object.keys(game.relics).forEach(id=>{const c=document.createElement('span');c.className='relic-chip '+(save.inheritance.relicId===id?'inherit':'');c.textContent=relicById[id].name+' ×'+game.relics[id]+(game.evolutions[id]?' · '+evolutions[id].find(x=>x[0]===game.evolutions[id])[1]:'');l.appendChild(c)});o.querySelector('#pauseEffects').innerHTML=(game.altarEffects||[]).map(x=>`<span class="relic-chip">祭坛：${x}</span>`).join('')+`<span class="relic-chip">技能：${skillDefs[game.skill].name}</span>`+activeSynergies().map(s=>`<span class="relic-chip syn" title="${s.desc}">协同：${s.name} Lv${synergyLevel(s)}</span>`).join('')+checkAntiSynergies().map(a=>`<span class="relic-chip anti" title="${a.penalty}">反协同：${a.desc}</span>`).join('')+(has('collector')?`<span class="relic-chip">囤积者：${game.hoarderStacks||0} 栈</span>`:'');o.querySelector('#resume').onclick=pause}
function calcShards(raw,bonus=false){let final=raw<=60?raw:raw<=150?60+(raw-60)*.7:raw<=400?123+(raw-150)*.5:248+(raw-400)*.35;return Math.floor(final*(bonus?1.15:1))}
function die(reason){if(game.ended)return;game.ended=true;state=STATES.GAMEOVER;game.deathReason=reason;SFX.death();flash('#ff0000',.5);shake(12,.4);if(game.tutorial){game.tutorial=null;const tb=document.getElementById('tutorialBox');if(tb)tb.remove()}const raw=game.score/10+game.elapsed/2+game.level*5+game.bountyCount*8;const final=calcShards(raw,save.unlockedMetaUpgrades.shardbonus);game.raw=raw;game.final=Math.max(0,final);save.currency+=game.final;save.stats.runs++;save.stats.bestScore=Math.max(save.stats.bestScore,game.score);save.stats.bestLevel=Math.max(save.stats.bestLevel,game.level);save.stats.bestBountyCount=Math.max(save.stats.bestBountyCount,game.bountyCount);checkAchievement('first_run',save.stats.runs);checkAchievement('score_1000',game.score);checkAchievement('bounty_5',game.bountyCount);checkAchievement('threat_10_60s',game.achievementTracking.threat10Timer);if(!save.unlockedMetaUpgrades.achievement){save.unlockedMetaUpgrades.achievement=true;save.currency+=25}persist();showGameover()}
function showGameover(){const o=document.createElement('div');o.className='overlay';o.id='gameoverOverlay';o.tabIndex=-1;o.innerHTML=`<div class="overlay-card"><div class="between"><div><h2>本局结束</h2><p class="hint">${game.deathReason} · 种子 ${game.seedText}</p></div><span class="pill">悬赏 ${game.bountyCount}</span></div><div class="stat-grid"><div class="stat"><small>得分</small><b>${fmt(game.score)}</b></div><div class="stat"><small>存活时间</small><b>${Math.floor(game.elapsed)}s</b></div><div class="stat"><small>等级</small><b>${game.level}</b></div><div class="stat"><small>原始碎片</small><b>${Math.floor(game.raw)}</b></div><div class="stat"><small>递减后</small><b>${game.final}</b></div><div class="stat"><small>Build</small><b>${Object.keys(game.relics).length}</b></div></div><h3>最终遗物与进化</h3><div id="finalRelics" class="relic-list" style="margin:8px 0 15px"></div><div id="finalEffects" class="relic-list" style="margin:8px 0 15px"></div><div class="row"><button id="again" class="primary">R 重新开始</button><button id="toMenu">M 返回菜单</button>${save.unlockedMetaUpgrades.inherit&&Object.keys(game.relics).length?'<button id="inheritBtn">I 选择传承</button>':''}</div><p class="hint" style="margin-top:10px">快捷键：R 重新开始 · M/Esc 返回菜单${save.unlockedMetaUpgrades.inherit&&Object.keys(game.relics).length?' · I 选择传承':''}</p></div>`;$('#gameWrap').appendChild(o);o.focus();Object.keys(game.relics).forEach(id=>{const c=document.createElement('span');c.className='relic-chip';c.textContent=relicById[id].name+' ×'+game.relics[id]+(game.evolutions[id]?' · '+evolutions[id].find(x=>x[0]===game.evolutions[id])[1]:'');o.querySelector('#finalRelics').appendChild(c)});o.querySelector('#finalEffects').innerHTML=(game.altarEffects||[]).map(x=>`<span class="relic-chip">祭坛：${x}</span>`).join('')+`<span class="relic-chip">主动技能：${skillDefs[game.skill].name}</span>`;o.querySelector('#again').onclick=()=>{o.remove();newGame()};o.querySelector('#toMenu').onclick=()=>{o.remove();showScreen('menu');state=STATES.MENU};o.querySelector('#inheritBtn')?.addEventListener('click',()=>{o.remove();state=STATES.INHERIT_CHOICE;showInheritance()})}
function showInheritance(){showChoiceOverlay('锁定一件传承遗物',Object.keys(game.relics).filter(id=>id!=='mark').map(id=>relicById[id]),id=>{save.inheritance={enabled:true,relicId:id,keepStack:save.unlockedMetaUpgrades.inherit_stack?stacks(id):1,evolution:game.evolutions[id]||null,lockedAt:Date.now()};persist();showScreen('menu');state=STATES.MENU;beep(920,.15,'triangle')},'永久锁定')}
/* ---------- 悬赏与威胁 ---------- */
function startBounty(){const d=pick(bountyDefs,game.r);game.bounty={...d,startedAt:game.elapsed,startFood:game.foodCount,startKills:game.enemyKills,startTurns:game.turns,startGold:game.goldEaten,startLevel:game.level,startClose:game.closeEat};game.bountyTimer=d.dur;game.bountyCount=game.bountyCount||0;game.bountyCombo=game.bountyCombo||0;updateHud()}
function updateBounty(dt){if(game.threat<10)return;if(!game.bounty)startBounty();game.bountyTimer-=dt;if(game.bounty.test(game)){completeBounty();return}if(game.bountyTimer<=0){game.bounty=null;game.bountyTimer=0;game.bountyCombo=0;startBounty()}}
function completeBounty(){const bonus=has('bounty')?1.35:1;const mult=game.bountyMultiplier>1?game.bountyMultiplier:1;if(mult>1){game.bountyMultiplier=1;game.floaters.push({x:GRID/2,y:3,text:'悬赏奖励 ×'+mult,color:'#ffd166',life:1.6})}game.bountyCount++;game.bountyCombo++;addScore(80*bonus*mult*(game.bountyCombo>=3?2:1),'悬赏');game.floaters.push({x:GRID/2,y:2,text:'目标完成 ×'+game.bountyCombo,color:'#ffd166',life:1});SFX.bountyComplete();if(game.bountyCombo===5){game.xp=game.xpNeed;synergyPulse('悬赏大师：免费升级')}game.bounty=null;startBounty()}
function updateThreat(dt=.016){
 const antiSpeed=checkAntiSynergies().some(a=>a.desc==='裂隙钥匙 + 时间腐蚀')?1.25:1,speed=has('time')?1.2*antiSpeed:antiSpeed,next=clamp(1+Math.floor(game.elapsed/(30/speed)),1,10);
 if(next>game.threat){game.threat=next;if(next<10)for(let i=0;i<Math.floor(next/2);i++)spawnEnemy('normal')}
 if(game.threat===10&&!game.capAnnounced){game.capAnnounced=true;game.capToast=true;SFX.threatCap();flash('#bd7bff',.4);shake(6,.25)}
 for(const [type,threshold,interval] of [['guardian',3,20],['bomber',6,30],['splitter',7,25],['summoner',8,40]]){
   if(game.threat<threshold)continue;game.enemySpawnTimers[type]-=dt;
   if(game.enemySpawnTimers[type]<=0){spawnEnemy(type);game.enemySpawnTimers[type]=interval}
 }
}
const baseUpdateThreat=updateThreat;
updateThreat=function(dt=.016){baseUpdateThreat(dt);if(!game||game.threat<4)return;const specialCount=game.enemies.filter(e=>e.special).length;if(specialCount>=4)return;game.specialEnemyTimer=(game.specialEnemyTimer||0)-dt;if(game.specialEnemyTimer>0)return;const choices=[];if(game.threat>=4)choices.push('charger');if(game.threat>=5)choices.push('sentinel');if(game.threat>=6)choices.push('burrower');if(game.threat>=7)choices.push('leech');if(game.threat>=8)choices.push('mirror');const type=pick(choices,game.r);if(spawnEnemy(type))game.specialEnemyTimer=18};
/* ---------- 更新、绘制 ---------- */
function tick(dt){if(!game||state!==STATES.PLAYING)return;if(game.tutorial)checkTutorialTrigger();if(state!==STATES.PLAYING)return;checkPendingEvolutions();if(state!==STATES.PLAYING)return;if(game.screenShake.duration>0){game.screenShake.duration-=dt;if(game.screenShake.duration<=0){game.screenShake.intensity=0;game.screenShake.duration=0}}game.attackCooldown=Math.max(0,game.attackCooldown-dt);game.attackPulse=Math.max(0,game.attackPulse-dt);game.invuln=Math.max(0,game.invuln-dt);game.shield=Math.max(0,game.shield-dt);game.elapsed+=dt;game.achievementTracking.noEatTimer+=dt;if(game.threat>=5)game.achievementTracking.threat5Timer+=dt;if(game.threat===10)game.achievementTracking.threat10Timer+=dt;if(game.enemies.length>=5)game.achievementTracking.perfectDodgeTimer+=dt;else{game.achievementTracking.perfectDodgeTimer=0}if(game.achievementTracking.threat5Timer>=30)checkAchievement('threat_5',30);if(game.achievementTracking.threat10Timer>=60)checkAchievement('threat_10_60s',60);if(game.achievementTracking.noEatTimer>=60)checkAchievement('no_eat_60s',1);if(game.achievementTracking.perfectDodgeTimer>=30&&game.achievementTracking.perfectDodgeKills===0)checkAchievement('perfect_dodge',1);game.summonShieldCooldown=Math.max(0,(game.summonShieldCooldown||0)-dt);if(hasSyn('召唤流')&&game.allies.length>0&&game.summonShieldCooldown<=0){grantShield(1,'召唤流');game.summonShieldCooldown=4;}updateThreat(dt);updateBounty(dt);moveEnemies(dt);if(state!==STATES.PLAYING)return;if(game.comboTimer>0){game.comboTimer-=dt;if(game.comboTimer<=0){game.combo=0;game.comboTimer=0}}if(game.frenzy>0){game.frenzy-=dt;if(game.frenzy<=0){SFX.frenzyEnd();game.frenzy=0;game.combo=0;game.comboTimer=0;game.floaters.push({x:GRID/2,y:1,text:'狂热结束',color:'#8ca1c2',life:1})}}if(game.frenzyFlash>0)game.frenzyFlash-=dt;if(has('armor')){game.armorChargeTimer-=dt;if(game.armorChargeTimer<=0){if(game.armorCharges<maxArmor()){game.armorCharges++;game.floaters.push({x:GRID/2,y:1,text:'甲壳充能 +1（'+game.armorCharges+'/'+maxArmor()+'）',color:'#66f2a2',life:.9})}game.armorChargeTimer=10}}if(game.echoActive){game.echoTimer-=dt;if(game.echoTimer<=0){game.echoActive=false;game.floaters.push({x:GRID/2,y:1,text:'回响结束',color:'#8ca1c2',life:.8})}}if(game.huntwindStacks>0){game.huntwindDecay=(game.huntwindDecay||0)+dt;if(game.huntwindDecay>=2){game.huntwindStacks=0;game.huntwindDecay=0}}if(game.evolutions.magnet==='storm'&&game.frenzy>0){game.stormTimer-=dt;if(game.stormTimer<=0){damageNearby(4);game.stormTimer=1}}if(game.skillCooldown>0)game.skillCooldown=Math.max(0,game.skillCooldown-dt);if(game.skillActive>0)game.skillActive=Math.max(0,game.skillActive-dt);if(game.skillBait>0){game.skillBait-=dt;if(game.skillBait<=0)game.bait=null}if(game.greedContract>0){game.greedContract-=dt;if(Math.floor(game.greedContract)%8===0&&Math.floor(game.greedContract+dt)%8!==0&&game.snake.length>3)game.snake.pop()}game.altarCooldown-=dt;if(!game.altar&&game.altarCooldown<=0){spawnAltar();game.altarCooldown=game.threat>=10?24:36}const interval=clamp(160-game.level*4-(game.frenzy>0?15:0)-(game.skillActive>0?45:0)-(has('swift')?stacks('swift')*6:0)-(has('symbiote')&&game.allies.length?8:0)-(game.huntwindStacks||0)*2,80,220);game.moveInterval=interval;acc+=dt*1000;while(acc>=interval&&state===STATES.PLAYING){acc-=interval;moveTick()}if(state!==STATES.PLAYING)return;if(has('magnet')){const range=game.evolutions.magnet==='gravity'?7:2+stacks('magnet');const mh=game.snake[0];for(const f of game.food){const d=Math.abs(f.x-mh.x)+Math.abs(f.y-mh.y);if(d<=range&&d>0){f.x+=Math.sign(mh.x-f.x);f.y+=Math.sign(mh.y-f.y)}}const hit=game.food.findIndex(f=>f.x===mh.x&&f.y===mh.y);if(hit>=0){const f=game.food.splice(hit,1)[0];eat(f);spawnFood()}}if(game.elapsed-game.lastEat>7&&has('greed')&&game.snake.length>3){game.snake.pop();game.lastEat=game.elapsed}if(game.affix==='虫巢'&&Math.floor(game.elapsed)%10===0&&Math.floor((game.elapsed-dt))%10!==0)spawnEnemy();if(game.threat>=5&&Math.floor(game.elapsed)%15===0&&Math.floor((game.elapsed-dt))%15!==0)spawnEnemy('tracker');for(const o of game.obstacles)o.life-=dt;game.obstacles=game.obstacles.filter(o=>o.life>0);for(const f of game.food)f.life+=dt;game.food=game.food.filter(f=>!f.expires||f.life<f.expires);for(const p of game.particles)p.life-=dt;game.particles=game.particles.filter(p=>p.life>0);for(const f of game.floaters)f.life-=dt;game.floaters=game.floaters.filter(f=>f.life>0);updateHud()}
function burst(x,y,color,type='radial'){if(!game)return;const n=type==='explosion'?20:type==='trail'?6:12;const room=200-game.particles.length;if(room<=0)return;const count=Math.min(n,room);for(let i=0;i<count;i++){let vx,vy,life,size;if(type==='explosion'){const a=(i/count)*Math.PI*2,sp=5+game.r()*4;vx=Math.cos(a)*sp;vy=Math.sin(a)*sp;life=1.5;size=4}else if(type==='sparkle'){vx=(game.r()-.5)*3;vy=(game.r()-.5)*3-2;life=.8;size=2}else if(type==='trail'){vx=game.dir.x*2+(game.r()-.5);vy=game.dir.y*2+(game.r()-.5);life=.6;size=2}else{vx=(game.r()-.5)*7;vy=(game.r()-.5)*7;life=1;size=3}game.particles.push({x,y,vx,vy,color,life,maxLife:life,size})}}
const tickCore=tick;tick=function(dt){if(state!==STATES.PLAYING)return;tickCore(dt);if(!game||state!==STATES.PLAYING)return;if(game.frenzy>0&&game.r()<.3){const fh=game.snake[0];if(fh)burst(fh.x,fh.y,'#ffd166','trail')}if(has('thorn')&&game.turns!==game.lastTrailTurn){game.lastTrailTurn=game.turns;const tail=game.snake.at(-1);if(tail)game.obstacles.push({x:tail.x,y:tail.y,life:(game.evolutions.thorn==='corridor'?6:2)*(hasAnti('phase','thorn')?.5:1),thorn:true,venom:game.evolutions.thorn==='venom'})}for(const o of game.obstacles.filter(o=>o.thorn)){const e=game.enemies.find(e=>e.x===o.x&&e.y===o.y);if(e){if(o.venom)e.slow=2;damageEnemy(e,1,'荆棘尾迹')}}};
const baseExtendedTick=tick;
tick=function(dt){if(state!==STATES.PLAYING)return;baseExtendedTick(dt);if(!game||state!==STATES.PLAYING)return;updateTerrain(dt);terrainDamage();if(game.terrain&&game.terrain.swamp)acc=Math.max(0,acc-dt*180);if(game.terrain&&game.terrain.id==='ice'&&game.terrain.slide>0){const t=game.terrain,n=t.slide;t.slide=0;t.sliding=true;try{for(let i=0;i<n&&state===STATES.PLAYING;i++)moveTick()}finally{t.sliding=false}}if(has('decoy')){game.decoyTimer=(game.decoyTimer||12)-dt;if(game.decoyTimer<=0){game.decoyTimer=12;game.bait={x:game.snake[0].x,y:game.snake[0].y};game.skillBait=1;game.floaters.push({x:game.snake[0].x,y:game.snake[0].y,text:'诱导信标',color:'#ffd166',life:1})}}};
function draw(){const c=$('#canvas'),ctx=c.getContext('2d');ctx.clearRect(0,0,SIZE,SIZE);let offsetX=0,offsetY=0;if(game&&game.screenShake.intensity>0){const currentIntensity=game.screenShake.intensity*Math.min(1,game.screenShake.duration/.2);offsetX=(Math.random()-.5)*currentIntensity*2;offsetY=(Math.random()-.5)*currentIntensity*2}ctx.save();ctx.translate(offsetX,offsetY);ctx.fillStyle=game&&game.frenzy>0?'#191b10':'#0b1510';ctx.fillRect(0,0,SIZE,SIZE);for(let y=0;y<GRID;y++)for(let x=0;x<GRID;x++){ctx.strokeStyle=(x+y)%2?'#142219':'#17271d';ctx.strokeRect(x*CELL,y*CELL,CELL,CELL)}if(!game){ctx.restore();return}const inset=game.affix==='狭间'?1:game.threat>=4?0:0;if(inset){ctx.fillStyle='#090d17';ctx.fillRect(0,0,SIZE,inset*CELL);ctx.fillRect(0,SIZE-inset*CELL,SIZE,inset*CELL);ctx.fillRect(0,0,inset*CELL,SIZE);ctx.fillRect(SIZE-inset*CELL,0,inset*CELL,SIZE)}for(const o of game.obstacles){ctx.fillStyle='#6b3441';ctx.fillStyle=o.thorn?'#66f2a2':'#6b3441';ctx.globalAlpha=o.thorn?.5:1;ctx.fillRect(o.x*CELL+8,o.y*CELL+8,CELL-16,CELL-16);ctx.globalAlpha=1}if(game.altar){const ax=(game.altar.x+.5)*CELL,ay=(game.altar.y+.5)*CELL;ctx.shadowBlur=22;ctx.shadowColor='#ff66cc';ctx.fillStyle='#ff77c8';ctx.beginPath();ctx.arc(ax,ay,9+Math.sin(performance.now()/180)*2,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ffb0ed';ctx.lineWidth=2;ctx.beginPath();ctx.arc(ax,ay,CELL*.7,0,Math.PI*2);ctx.stroke();ctx.shadowBlur=0}for(const f of game.food){const x=(f.x+.5)*CELL,y=(f.y+.5)*CELL;ctx.shadowBlur=f.gold?18:10;ctx.shadowColor=f.gold?'#ffd166':'#66f2a2';ctx.fillStyle=f.gold?'#ffd166':'#66f2a2';ctx.beginPath();ctx.arc(x,y,f.gold?7:5,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}for(const e of game.enemies){let ec='#b85cff';if(e.type==='tracker')ec='#ff647c';else if(e.type==='guardian')ec='#4a7c9e';else if(e.type==='bomber')ec='#ff8a4c';else if(e.type==='splitter'||e.type==='splitter_small')ec='#9d6bff';else if(e.type==='summoner')ec='#d4af37';const flashAlpha=e.type==='bomber'&&e.chargeTimer>0?0.5+0.5*Math.sin(performance.now()/50):1;ctx.globalAlpha=flashAlpha;for(let k=e.trail;k>=1;k--){const bx=clamp(e.x-e.dx*k,0,GRID-1),by=clamp(e.y-e.dy*k,0,GRID-1);ctx.globalAlpha=flashAlpha*(0.72-k*.1);ctx.fillStyle=ec;ctx.beginPath();if(e.type==='guardian'){ctx.strokeStyle=ec;ctx.lineWidth=2;ctx.strokeRect(bx*CELL+4,by*CELL+4,CELL-8,CELL-8)}else{ctx.roundRect(bx*CELL+4,by*CELL+4,CELL-8,CELL-8,5);ctx.fill()}}ctx.globalAlpha=1;const ex=(e.x+.5)*CELL,ey=(e.y+.5)*CELL;ctx.shadowBlur=10;ctx.shadowColor=ec;ctx.fillStyle=e.hit>0?'#ffffff':ec;if(e.type==='guardian'){ctx.strokeStyle=ec;ctx.lineWidth=3;ctx.strokeRect(ex-CELL*.38,ey-CELL*.38,CELL*.76,CELL*.76)}else if(e.type==='summoner'){ctx.fillStyle='#d4af37';ctx.shadowBlur=18;ctx.shadowColor='#d4af37';for(let i=0;i<3;i++){ctx.beginPath();ctx.arc(ex,ey,CELL*.5+i*3,0,Math.PI*2);ctx.stroke()}ctx.shadowBlur=10}else{ctx.beginPath();const size=e.type==='splitter_small'?.23:.38;ctx.roundRect(ex-CELL*size,ey-CELL*size,CELL*size*2,CELL*size*2,7);ctx.fill()}ctx.shadowBlur=0;if(e.type!=='summoner'){ctx.fillStyle='#fff';const ox=e.dx*3,oy=e.dy*3;ctx.beginPath();ctx.arc(ex+ox-3,ey+oy-3,2,0,7);ctx.arc(ex+ox+3,ey+oy+3,2,0,7);ctx.fill()}if(e.type==='guardian'){for(let hp=0;hp<2;hp++){ctx.fillStyle=hp<e.hp?'#a8e2ff':'#263648';ctx.fillRect(ex-9+hp*10,ey-20,7,3)}}if(e.type==='bomber'&&e.chargeTimer>0){ctx.strokeStyle='#ff8a4c';ctx.lineWidth=2;ctx.strokeRect((e.x-1)*CELL,(e.y-1)*CELL,3*CELL,3*CELL);ctx.fillStyle='#fff1d8';ctx.font='bold 12px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(Math.ceil(e.chargeTimer*10)/10,ex,ey)}}if(game.attackPulse>0){const h=game.snake[0];ctx.strokeStyle='#66f2a2';ctx.lineWidth=3;ctx.globalAlpha=game.attackPulse/.3;ctx.beginPath();ctx.arc((h.x+.5)*CELL,(h.y+.5)*CELL,(1-game.attackPulse/.3)*(COMBAT.radius+.5)*CELL,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}for(const a of game.allies){ctx.fillStyle='#66f2a2';ctx.shadowBlur=9;ctx.shadowColor='#66f2a2';ctx.beginPath();ctx.arc((a.x+.5)*CELL,(a.y+.5)*CELL,5,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}game.snake.forEach((s,i)=>{const t=Math.min(1,acc/(game.moveInterval||160));const x=(s.px+(s.x-s.px)*t+.5)*CELL,y=(s.py+(s.y-s.py)*t+.5)*CELL;ctx.shadowBlur=i===0?16:8;ctx.shadowColor=i===0?'#a2edbb':'#67bb85';ctx.fillStyle=i===0?'#d9f8e3':`hsl(${145-i},45%,${58-Math.min(24,i)}%)`;ctx.beginPath();ctx.roundRect(x-CELL*.38,y-CELL*.38,CELL*.76,CELL*.76,7);ctx.fill();ctx.shadowBlur=0;if(i===0){ctx.fillStyle='#06101b';const ex=game.dir.x?x+game.dir.x*4:x-4,ey=game.dir.y?y+game.dir.y*4:y-4;ctx.beginPath();ctx.arc(ex-2,ey-2,2,0,7);ctx.arc(ex+2,ey+2,2,0,7);ctx.fill()}});for(const p of game.particles){const prog=clamp(p.life/(p.maxLife||1),0,1);ctx.globalAlpha=prog;ctx.fillStyle=p.color;const psize=Math.max(.5,(p.size||3)*prog);ctx.beginPath();ctx.arc((p.x+.5)*CELL,(p.y+.5)*CELL,psize,0,6.2832);ctx.fill();p.x+=p.vx*.02;p.y+=p.vy*.02}for(const f of game.floaters.slice(-12)){ctx.globalAlpha=Math.min(1,f.life*2);ctx.fillStyle=f.color;ctx.font='600 14px Microsoft YaHei, sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(f.text,clamp((f.x+.5)*CELL,60,SIZE-60),(f.y+.5)*CELL-(1-Math.min(1,f.life))*24)}ctx.globalAlpha=1;if(game.flashEffect.intensity>0){ctx.fillStyle=game.flashEffect.color||'#ffffff';ctx.globalAlpha=clamp(game.flashEffect.intensity,0,1);ctx.fillRect(0,0,SIZE,SIZE);ctx.globalAlpha=1;game.flashEffect.intensity*=.85;if(game.flashEffect.intensity<.01){game.flashEffect.intensity=0;game.flashEffect.color=null}}if(game.capToast){const d=document.createElement('div');d.className='cap-toast';d.textContent='终局悬赏开始';$('#toastLayer').appendChild(d);setTimeout(()=>d.remove(),1100);game.capToast=false}ctx.restore()}
function popNum(el,val){if(!el)return;const v=String(val);if(el.dataset.v===v)return;const first=el.dataset.v===undefined;el.dataset.v=v;if(first)return;el.classList.remove('number-pop');void el.offsetWidth;el.classList.add('number-pop')}
function updateHud(){if(!game)return;updateCombatHud();$('#scoreHud').textContent=fmt(game.score);$('#levelHud').textContent=game.level;$('#regionHud').textContent='区域 '+game.region;$('#threatHud').textContent=game.threat;$('#capMark').textContent=game.threat===10?'◆ 封顶':'';$('#affixHud').textContent=game.affix+' · '+(affixes.find(a=>a[0]===game.affix)?.[1]||'');$('#xpBar').style.width=clamp(game.xp/game.xpNeed*100,0,100)+'%';$('#comboCount').textContent=game.combo;$('#comboTimer').textContent=game.comboTimer>0?game.comboTimer.toFixed(1)+'s':'--';const sk=skillDefs[game.skill];$('#skillHud').className='hud-box skill-box '+(game.skillCooldown<=0?'ready':'');$('#skillHud').innerHTML=`${sk.icon} ${sk.name} <strong>[空格]</strong><br><span>${game.skillCooldown>0?game.skillCooldown.toFixed(1)+'s 冷却':'就绪'}</span>`;$('#frenzyFrame').classList.toggle('hidden',game.frenzy<=0);const b=$('#bountyHud');if(game.threat>=10&&game.bounty){b.classList.remove('hidden');b.innerHTML=`<strong>终局悬赏</strong>　${game.bounty.desc}<br><span class="timer">${Math.ceil(game.bountyTimer)}s · 连击 ${game.bountyCombo}${game.bountyMultiplier>1?' · 奖励 ×'+game.bountyMultiplier:''}</span>`}else b.classList.add('hidden');if(game.mark){if(!$('#markHint')){const hint=document.createElement('div');hint.id='markHint';hint.className='hud-box mark-hint';$('#skillHud').parentElement.appendChild(hint)}$('#markHint').textContent='按 Q 使用传承印记'}else{const hint=$('#markHint');if(hint)hint.remove()}const ih=$('#inheritHud');if(ih){const inh=save.inheritance&&save.inheritance.relicId;if(inh&&relicById[inh]){const r=relicById[inh];const ev=game.evolutions[inh]&&evolutions[inh]?evolutions[inh].find(x=>x[0]===game.evolutions[inh])[1]:'';ih.classList.remove('hidden');ih.innerHTML='传承 '+r.name+' ×'+stacks(inh)+(ev?' · '+ev:'');ih.title=r.desc}else ih.classList.add('hidden')}const bh=$("#buildHud");if(bh){const build=Object.keys(game.relics).filter(id=>game.relics[id]>0).map(id=>relicById[id].name+" ×"+game.relics[id]).join(" · ");bh.classList.toggle("hidden",!build);bh.textContent=build?"构筑："+build:"";bh.title="当前遗物与层数"}const sh=$('#synergyHud');if(sh){const syns=activeSynergies(),antis=checkAntiSynergies();if(syns.length||antis.length){sh.classList.remove('hidden');sh.innerHTML='⚡ 协同：'+(syns.length?syns.map(s=>s.name+' Lv'+synergyLevel(s)).join(' · '):'—')+(antis.length?'<br><span class="anti">⚠ 反协同：'+antis.map(a=>a.desc).join('、')+'</span>':'')}else sh.classList.add('hidden')}const hh=$('#hoarderHud');if(hh){if(has('collector')&&game.hoarderStacks>0){hh.classList.remove('hidden');hh.innerHTML='囤积者：'+game.hoarderStacks+' 栈 <strong>[E 兑换]</strong>'}else hh.classList.add('hidden')}popNum($('#scoreHud'),game.score);popNum($('#levelHud'),game.level);popNum($('#threatHud'),game.threat)}function loop(t){const dt=Math.min(.05,(t-last)/1000||0);last=t;try{if(state===STATES.PLAYING)tick(dt);else if(game&&game.screenShake.duration>0){game.screenShake.duration=Math.max(0,game.screenShake.duration-dt);if(!game.screenShake.duration)game.screenShake.intensity=0}draw()}catch(err){reportFrameError(err)}raf=requestAnimationFrame(loop)}

function updateCombatHud(){
 $('#lengthHud').textContent=game.snake.length;$('#killsHud').textContent=game.enemyKills;
 $('#timeHud').textContent=Math.floor(game.elapsed/60).toString().padStart(2,'0')+':'+Math.floor(game.elapsed%60).toString().padStart(2,'0');
 $('#healthHud').textContent=game.invuln>0?'无敌 '+game.invuln.toFixed(1)+'s':game.shield>0?'护盾 '+game.shield.toFixed(1)+'s':has('armor')?'甲壳 '+game.armorCharges+'/'+maxArmor():game.snake.length>=6?'可撞击敌人':'避碰 · J 冲击';
 $('#enemyCountHud').textContent=game.enemies.length;
 $('#attackBtn').disabled=state!==STATES.PLAYING||game.attackCooldown>0;
 $('#attackBtn').innerHTML='<span>范围冲击</span><kbd>J</kbd><small>'+(game.attackCooldown>0?game.attackCooldown.toFixed(1)+'s':'就绪 · 两格范围')+'</small>';
 $('#skillBtn').disabled=state!==STATES.PLAYING||game.skillCooldown>0;
 $('#redeemBtn').classList.toggle('hidden',!has('collector'));$('#redeemBtn').disabled=state!==STATES.PLAYING||game.hoarderStacks<=0;
}
/* ---------- 视觉反馈系统 ---------- */

function shake(intensity=5,duration=.2){if(!save.settings.screenShake||!game)return;game.screenShake.intensity=Math.max(game.screenShake.intensity,intensity);game.screenShake.duration=Math.max(game.screenShake.duration,duration)}
function flash(color,intensity=.3){if(!game)return;game.flashEffect.color=color;game.flashEffect.intensity=intensity}
const SFX={eatNormal:()=>beep(520,.06,'sine'),eatGold:()=>beep(880,.08,'sine'),levelUp:()=>{beep(760,.08,'triangle');setTimeout(()=>beep(960,.08,'triangle'),80)},killEnemy:()=>beep(180,.12,'square'),explosion:()=>{beep(80,.15,'sawtooth');setTimeout(()=>beep(120,.12,'square'),50)},comboHit:()=>beep(640+game.combo*60,.05,'sine'),frenzyStart:()=>{beep(1040,.1,'square');setTimeout(()=>beep(1320,.12,'triangle'),100)},frenzyEnd:()=>beep(440,.15,'sine'),skillDash:()=>beep(680,.08,'triangle'),skillPhase:()=>{beep(520,.06,'sine');setTimeout(()=>beep(820,.06,'sine'),60)},skillBait:()=>beep(740,.1,'triangle'),skillTail:()=>{beep(380,.1,'square');setTimeout(()=>beep(520,.08,'triangle'),80)},relicGet:()=>beep(700,.12,'triangle'),evolution:()=>{beep(980,.16,'triangle');setTimeout(()=>beep(1240,.12,'sine'),120)},buttonClick:()=>beep(520,.04,'sine'),buttonHover:()=>beep(440,.03,'sine'),refresh:()=>beep(400,.05,'square'),altarAppear:()=>beep(620,.14,'triangle'),bountyComplete:()=>{beep(980,.1,'triangle');setTimeout(()=>beep(1240,.1,'triangle'),100);setTimeout(()=>beep(1560,.12,'sine'),200)},threatCap:()=>{beep(740,.16,'triangle');setTimeout(()=>beep(880,.14,'triangle'),120)},death:()=>{beep(220,.15,'sawtooth');setTimeout(()=>beep(160,.2,'sawtooth'),100);setTimeout(()=>beep(120,.25,'sawtooth'),200)}};
document.addEventListener('click',e=>{if(e.target.tagName==='BUTTON'&&!e.target.disabled)SFX.buttonClick()});
/* ---------- 新手教学 ---------- */
const tutorialSteps=[
 {id:'move',title:'移动控制',desc:'使用方向键或 WASD 控制蛇头移动，吃到食物会让蛇变长。',trigger:()=>true,position:'center'},
 {id:'combo',title:'连吃与狂热',desc:'5 秒内连续吃到食物会累积连击。达到 5 连吃后进入狂热：移动更快、分值翻倍、金色食物概率提升。',trigger:()=>game.combo>=3,position:'top'},
 {id:'upgrade',title:'升级与遗物',desc:'吃够食物就会升级，从 3 张遗物卡中选 1 张。同类遗物叠到 3 层可以进化。',trigger:()=>game.level>=2,position:'center'},
 {id:'skill',title:'主动技能',desc:'按空格键使用主动技能，右侧 HUD 会显示冷却与就绪状态。',trigger:()=>game.skillCooldown===0&&game.level>=2,position:'right'},
 {id:'threat',title:'威胁与敌人',desc:'威胁等级会随时间上升，敌人越来越多。按 J 释放两格冲击，空格冲刺可迎击敌人。守卫有两格血；长到 6 节后也能撞击攻击。',trigger:()=>game.threat>=2||game.enemies.length>0,position:'top-right'}
];
function showTutorialStep(step){if(!game||!game.tutorial)return;const t=tutorialSteps[step];if(!t||game.tutorial.completed.includes(t.id))return;const old=document.getElementById('tutorialBox');if(old)old.remove();const box=document.createElement('div');box.id='tutorialBox';box.className='tutorial-box tutorial-'+t.position;box.innerHTML='<div class="tutorial-content"><span class="pill">新手引导 '+(step+1)+'/'+tutorialSteps.length+'</span><h4>'+t.title+'</h4><p>'+t.desc+'</p><div class="row"><button id="tutorialNext">知道了 (Enter)</button><button id="tutorialSkip" class="skip">跳过教程</button></div></div>';$('#gameWrap').appendChild(box);state=STATES.PAUSED;$('#tutorialNext').onclick=()=>{if(!game||!game.tutorial){box.remove();state=STATES.PLAYING;return}game.tutorial.completed.push(t.id);game.tutorial.step++;box.remove();state=STATES.PLAYING;if(game.tutorial.step>=tutorialSteps.length){game.tutorial=null;save.settings.tutorialCompleted=true;persist();synergyPulse('教程完成')}};$('#tutorialSkip').onclick=()=>{game.tutorial=null;save.settings.tutorialCompleted=true;box.remove();state=STATES.PLAYING;persist()}}
function checkTutorialTrigger(){if(!game||!game.tutorial||state!==STATES.PLAYING)return;const step=tutorialSteps[game.tutorial.step];if(!step)return;if(game.tutorial.completed.includes(step.id)){game.tutorial.step++;return}if(step.trigger())showTutorialStep(game.tutorial.step)}
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&document.getElementById('tutorialBox')){e.preventDefault();const n=document.getElementById('tutorialNext');if(n)n.click()}},true);

function queueEvolution(id){
 if(game.evolutions[id]||game.pendingEvolutions.includes(id))return;
 game.pendingEvolutions.push(id);game.pendingEvolution=game.pendingEvolutions[0];
 const run=game;setTimeout(()=>{if(game===run)checkPendingEvolutions()},80);
}
function checkPendingEvolutions(){
 if(state!==STATES.PLAYING)return;
 const id=game.pendingEvolutions.find(id=>!game.deferredEvolutions.includes(id)&&!game.evolutions[id]);
 if(id)showEvolution(id);
}
const tickTerrainAdjust=tick;
tick=function(dt){tickTerrainAdjust(dt)};
const relicTick=tick;
tick=function(dt){relicTick(dt);if(game&&state===STATES.PLAYING&&has('seedbank')&&game.food.length<2&&game.r()<1-Math.pow(1-.02*stacks('seedbank'),dt*60))spawnFood()};
const baseShowUpgrade=showUpgrade;
showUpgrade=function(){baseShowUpgrade();const over=$('#upgradeOverlay');if(over){const hint=over.querySelector('.hint');if(hint)hint.textContent=hint.textContent.replace('空格/0/S','空格/0');const skip=over.querySelector('#skipRelic');if(skip)skip.textContent='空格/0 跳过'}};
document.addEventListener('keydown',e=>{if(state===STATES.UPGRADE_CHOICE&&(e.key==='s'||e.key==='S')){e.preventDefault();e.stopImmediatePropagation()}},true);
const baseMoveTick=moveTick;
const baseUpdateHud=updateHud;
updateHud=function(){baseUpdateHud();if(!game)return;const terrain=$('#terrainHud');if(terrain)terrain.textContent='地形：'+(game.terrain?game.terrain.name:'准备中')+' · '+(game.terrain?game.terrain.effect:'');const count=$('#enemyLegendHud');if(count)count.textContent='特殊敌人：'+game.enemies.filter(e=>e.special).length+' / 4 '+(terrainWarning()||'');};
const baseDraw=draw;
draw=function(){baseDraw();if(!game||!game.terrain)return;const ctx=$('#canvas').getContext('2d'),t=game.terrain;ctx.save();ctx.globalAlpha=.22;ctx.fillStyle=terrainDefs[t.id].color;for(const c of t.cells||[])ctx.fillRect(c.x*CELL+2,c.y*CELL+2,CELL-4,CELL-4);ctx.globalAlpha=.85;if(t.id==='lava')for(const h of t.hazards||[]){ctx.fillStyle=h.active?'#ff4f3d':'#8b4c3b';ctx.fillRect(h.x*CELL+5,h.y*CELL+5,CELL-10,CELL-10)}if(t.portals&&t.portals.length===2){ctx.strokeStyle='#d6a8ff';ctx.lineWidth=3;for(const p of t.portals){ctx.beginPath();ctx.arc((p.x+.5)*CELL,(p.y+.5)*CELL,CELL*.35,0,Math.PI*2);ctx.stroke()}}if(t.id==='wind'){ctx.fillStyle='#d2dcff';ctx.font='bold 18px Arial';ctx.fillText(t.wind.x>0?'→':'←',CELL*1,CELL*1.5)}if(t.id==='inversion'&&t.warning>0){ctx.strokeStyle='#f0a5ff';ctx.lineWidth=5;ctx.strokeRect(2,2,SIZE-4,SIZE-4)}ctx.restore()};
moveTick=function(){if(!game||state!==STATES.PLAYING)return;const h=game.snake[0],d=game.queue[0]||game.dir,nx=h.x+d.x,ny=h.y+d.y;if(terrainBlocked(nx,ny)){die('撞上遗迹墙');return}baseMoveTick();if(!game||state!==STATES.PLAYING)return;applyTerrainEnter(game.snake[0].x,game.snake[0].y);terrainDamage()};
const baseEnqueue=enqueue;
const brambleMoveTick=moveTick;
moveTick=function(){brambleMoveTick();if(game&&state===STATES.PLAYING&&game.obstacles.some(o=>o.bramble&&o.x===game.snake[0].x&&o.y===game.snake[0].y)){if(game.shield>0)game.shield--;else if(game.invuln<=0){game.invuln=.7;die('荆棘林')}}};
const baseExtendedDraw=draw;
draw=function(){baseExtendedDraw();if(!game)return;const ctx=$('#canvas').getContext('2d');ctx.save();for(const e of game.enemies.filter(e=>e.special)){const x=(e.x+.5)*CELL,y=(e.y+.5)*CELL;ctx.globalAlpha=.75;if(e.type==='charger'&&e.chargeTimer>0){ctx.strokeStyle='#ff3b4f';ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+e.dx*4*CELL,y+e.dy*4*CELL);ctx.stroke()}if(e.type==='sentinel'&&e.laserWarning&&e.laser){ctx.strokeStyle='#b86bff';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+e.laser.x*GRID*CELL,y+e.laser.y*GRID*CELL);ctx.stroke()}if(e.type==='burrower'&&e.hidden){ctx.strokeStyle='#c59670';ctx.setLineDash([3,3]);ctx.strokeRect(x-CELL*.5,y-CELL*.5,CELL,CELL);ctx.setLineDash([])}if(e.type==='leech'){ctx.strokeStyle='#3e7f55';ctx.beginPath();ctx.arc(x,y,CELL*.65,0,Math.PI*2);ctx.stroke()}if(e.type==='mirror'){ctx.strokeStyle='#7be9e9';ctx.globalAlpha=.45;ctx.strokeRect(x-CELL*.4,y-CELL*.4,CELL*.8,CELL*.8)}}ctx.restore()};
enqueue=function(d){if(game&&game.terrain&&game.terrain.id==='inversion'&&game.terrain.warning>0)d={x:-d.x,y:d.y};baseEnqueue(d);if(game&&has('afterimage')){game.afterimageTimer=(game.afterimageTimer||0)+1;if(game.afterimageTimer%2===0){const h=game.snake[0];game.obstacles.push({x:h.x,y:h.y,life:2,afterimage:true})}}};
const terrainAndEnemyDraw=baseDraw;
draw=function(){terrainAndEnemyDraw();if(!game)return;const ctx=$('#canvas').getContext('2d'),t=game.terrain;ctx.globalAlpha=.22;if(t){ctx.fillStyle=terrainDefs[t.id].color;for(const c of t.cells||[])ctx.fillRect(c.x*CELL+2,c.y*CELL+2,CELL-4,CELL-4);ctx.globalAlpha=.85;if(t.id==='lava')for(const h of t.hazards||[]){ctx.fillStyle=h.active?'#ff4f3d':'#8b4c3b';ctx.fillRect(h.x*CELL+5,h.y*CELL+5,CELL-10,CELL-10)}if(t.portals&&t.portals.length===2){ctx.strokeStyle='#d6a8ff';ctx.lineWidth=3;for(const p of t.portals){ctx.beginPath();ctx.arc((p.x+.5)*CELL,(p.y+.5)*CELL,CELL*.35,0,Math.PI*2);ctx.stroke()}}if(t.id==='wind'){ctx.fillStyle='#d2dcff';ctx.font='bold 18px Arial';ctx.fillText(t.wind.x>0?'→':'←',CELL,CELL*1.5)}if(t.id==='inversion'&&t.warning>0){ctx.strokeStyle='#f0a5ff';ctx.lineWidth=5;ctx.strokeRect(2,2,SIZE-4,SIZE-4)}}for(const e of game.enemies.filter(e=>e.special)){const x=(e.x+.5)*CELL,y=(e.y+.5)*CELL;ctx.globalAlpha=.75;ctx.fillStyle=e.type==='charger'?'#ff3b4f':e.type==='sentinel'?'#6f2a9f':e.type==='burrower'?'#8a6245':e.type==='leech'?'#2f6b45':'#55dada';ctx.beginPath();ctx.arc(x,y,CELL*.24,0,Math.PI*2);ctx.fill();if(e.type==='charger'&&e.chargeTimer>0){ctx.strokeStyle='#ff3b4f';ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+e.dx*4*CELL,y+e.dy*4*CELL);ctx.stroke()}if(e.type==='sentinel'&&e.laserWarning&&e.laser){ctx.strokeStyle='#b86bff';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+e.laser.x*GRID*CELL,y+e.laser.y*GRID*CELL);ctx.stroke()}if(e.type==='burrower'&&e.hidden){ctx.strokeStyle='#c59670';ctx.setLineDash([3,3]);ctx.strokeRect(x-CELL*.5,y-CELL*.5,CELL,CELL);ctx.setLineDash([])}if(e.type==='leech'){ctx.strokeStyle='#3e7f55';ctx.beginPath();ctx.arc(x,y,CELL*.65,0,Math.PI*2);ctx.stroke()}if(e.type==='mirror'){ctx.strokeStyle='#7be9e9';ctx.globalAlpha=.45;ctx.strokeRect(x-CELL*.4,y-CELL*.4,CELL*.8,CELL*.8)}}ctx.globalAlpha=1};
const visualDraw=draw;
draw=function(){visualDraw();if(!game)return;const ctx=$('#canvas').getContext('2d');for(const e of game.enemies.filter(e=>e.special&&e.hidden)){ctx.globalAlpha=.92;ctx.fillStyle='#0b1510';ctx.fillRect(e.x*CELL+1,e.y*CELL+1,CELL-2,CELL-2);ctx.globalAlpha=1}};
const baseUseAttack=useAttack;
useAttack=function(){if(state!==STATES.PLAYING||!game||game.attackCooldown>0)return;baseUseAttack();const h=game.snake[0],radius=COMBAT.radius+(has('shock')?stacks('shock'):0);const outside=game.enemies.filter(e=>Math.max(Math.abs(e.x-h.x),Math.abs(e.y-h.y))<=radius);outside.forEach(e=>{if(game.enemies.includes(e)&&Math.max(Math.abs(e.x-h.x),Math.abs(e.y-h.y))>COMBAT.radius)damageEnemy(e,1,'震荡线圈')});if(has('piercer')){const extra=game.enemies.find(e=>Math.max(Math.abs(e.x-h.x),Math.abs(e.y-h.y))<=radius);if(extra)damageEnemy(extra,1,'穿刺尖牙')}};
const baseKillEnemy=killEnemy;
killEnemy=function(enemy,reason='kill'){const type=enemy&&enemy.type,ok=baseKillEnemy(enemy,reason);if(ok&&game){if(has('voltage')){game.killStreak=(game.killStreak||0)+1;if(game.killStreak%3===0)game.skillCooldown=Math.max(0,game.skillCooldown-1)}if(has('scavenger')&&(type==='sentinel'||type==='bomber'))spawnFood(type==='sentinel')}};
const baseDie=die;
die=function(reason){if(game&&has('phoenix')&&!game.phoenixUsed&&state===STATES.PLAYING){game.phoenixUsed=true;removeSnakeSegments(game.snake.length,'余烬核心');game.invuln=1;grantShield(1,'余烬核心');game.floaters.push({x:game.snake[0].x,y:game.snake[0].y,text:'余烬核心：涅槃',color:'#ffb347',life:1.8});flash('#ff8a4c',.3);SFX.evolution();return}return baseDie(reason)};
/* ---------- 构筑信息与战斗反馈 ---------- */
function relicChoiceInfo(r){
  const next=Math.min(stacks(r.id)+1,r.max), notes=[];
  if(evolutions[r.id]&&!game.evolutions[r.id])notes.push(next>=3?'获得后可选择进化':'距离进化还需 '+(3-next)+' 层');
  const current=wouldTriggerAnti(r);
  for(const anti of antiSynergies){
    if(!current.includes(anti))continue;
    if(anti.conds.every(c=>c.type==='terrain'?game.terrain&&game.terrain.id===c.id:c.id===r.id||has(c.id)))notes.push('风险：'+anti.desc+'（'+anti.penalty+'）');
  }
  return notes.join(' · ');
}
const drawBeforeFeedback=draw;
draw=function(){
  drawBeforeFeedback();if(!game||!game.enemies.length)return;
  const ctx=$('#canvas').getContext('2d');ctx.save();
  for(const e of game.enemies){
    if(e.hidden)continue;
    const x=(e.x+.5)*CELL,y=e.y*CELL+3,w=CELL*.72;
    if(e.maxHp>1){ctx.fillStyle='#160f16';ctx.fillRect(x-w/2,y,w,3);ctx.fillStyle='#ff6b86';ctx.fillRect(x-w/2,y,w*clamp(e.hp/e.maxHp,0,1),3)}
    if(e.hit>0){ctx.strokeStyle='#ffffff';ctx.lineWidth=2;ctx.strokeRect(e.x*CELL+4,e.y*CELL+4,CELL-8,CELL-8)}
  }
  ctx.restore();
};
const pauseBeforeRules=showPause;
showPause=function(){
  pauseBeforeRules();const card=$('#pauseOverlay .overlay-card');
  const rules=document.createElement('div');rules.id='pauseRules';rules.className='pause-warning';
  const lines=['地形：'+(game.terrain?game.terrain.name:'无'),'区域词缀：'+game.affix,'威胁：'+game.threat+'/10','悬赏：'+(game.bounty?game.bounty.desc+' · '+Math.ceil(game.bountyTimer)+'s':'威胁封顶后开启'),'选卡保底：'+(game.forceRare?'下一次至少一张非普通':'无'),'囤积兑换：E（'+(game.hoarderStacks||0)+' 栈）'];
  for(const line of lines){const item=document.createElement('p');item.textContent=line;rules.appendChild(item)}
  card.appendChild(rules);
};
const tickBeforeVoid=tick;
tick=function(dt){
  if(state!==STATES.PLAYING)return;
  tickBeforeVoid(dt);if(!game||state!==STATES.PLAYING)return;
  if(has('voidmouth')){
    game.voidmouthTimer=(game.voidmouthTimer??10)-dt;
    while(game.voidmouthTimer<=0&&has('voidmouth')){
      game.voidmouthTimer+=10;
      const ids=Object.keys(game.relics).filter(id=>stacks(id)>0&&id!=='mark'&&id!=='voidmouth');
      if(ids.length){const id=pick(ids,game.r);game.relics[id]--;game.floaters.push({x:game.snake[0].x,y:game.snake[0].y,text:'虚空代价：'+relicById[id].name+' -1',color:'#ff77c8',life:1})}
    }
  }else game.voidmouthTimer=10;
};
const tickBeforeCaps=tick;
tick=function(dt){tickBeforeCaps(dt);if(!game)return;if(game.floaters.length>60)game.floaters.splice(0,game.floaters.length-60);if(game.log&&game.log.length>80)game.log.splice(0,game.log.length-80)};
